// org.programme.create — E1 AC1: the optional programme level under a client (SOP-DEL-02 §3), and a site
// placed in a programme of its own client. Generated by `pnpm gen:command`; guard cases kept.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  NotFound,
  openTestKernel,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';
import { createProgramme } from '../commands/create-programme.ts';
import { createSite } from '../commands/create-site.ts';

const director = aStaffActor({ roles: ['director'] });
const other = aStaffActor();
const place = { countryCode: 'LT', cityCode: 'VNO', cityName: 'Vilnius', name: 'Site 001', standard: 'S' };
let testDb: TestDatabase;
let t: TestKernel;
let clientC: string;
let clientA: string;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(director, createClient.permission, createProgramme.permission, createSite.permission);
  clientC = (
    await t.kernel.execute(createClient, director, { shortCode: 'CLIENTC', name: 'Client C' }, 'test')
  ).id;
  clientA = (
    await t.kernel.execute(createClient, director, { shortCode: 'CLIENTA', name: 'Client A' }, 'test')
  ).id;
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.programme.create', () => {
  it('refuses an actor without the permission', async () => {
    const attempt = t.kernel.execute(
      createProgramme,
      other,
      { clientId: clientC, name: 'Programme 1' },
      'test',
    );
    await expect(attempt).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses a programme without a name', async () => {
    const attempt = t.kernel.execute(createProgramme, director, { clientId: clientC, name: '' }, 'test');
    await expect(attempt).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('creates a programme under the client, audited; a site can be placed in it', async () => {
    const p = await t.kernel.execute(
      createProgramme,
      director,
      { clientId: clientC, name: 'Programme 1' },
      'test',
    );
    expect(
      await countRows(testDb.url, `audit_event WHERE command = 'org.programme.create' AND client_id = $1`, [
        clientC,
      ]),
    ).toBe(1);
    const s = await t.kernel.execute(
      createSite,
      director,
      { clientId: clientC, programmeId: p.id, ...place },
      'test',
    );
    expect(s.projectId).toBe('CLIENTC-LT-VNO-001');
    expect(await countRows(testDb.url, 'site WHERE id = $1 AND programme_id = $2', [s.id, p.id])).toBe(1);
  });

  it('refuses a second programme with the same name for the client, and an unknown client', async () => {
    await expect(
      t.kernel.execute(createProgramme, director, { clientId: clientC, name: 'Programme 1' }, 'test'),
    ).rejects.toBeInstanceOf(Conflict);
    await expect(
      t.kernel.execute(createProgramme, director, { clientId: randomUUID(), name: 'Programme 9' }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it("refuses a site in another client's programme", async () => {
    const p = await t.kernel.execute(
      createProgramme,
      director,
      { clientId: clientC, name: 'Programme 2' },
      'test',
    );
    await expect(
      t.kernel.execute(createSite, director, { clientId: clientA, programmeId: p.id, ...place }, 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });
});
